const rows = $input.all().map(i=>i.json).filter(r=>r&&r.watch_id);
function n(v){if(v===undefined||v===null)return '';let t=Array.isArray(v)?v.join(' '):(typeof v==='object'?JSON.stringify(v):String(v));return t.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/&/g,'').replace(/[^A-Z0-9]+/g,' ').replace(/\s+/g,' ').trim();}
function a(v){if(v===undefined||v===null||v==='')return [];if(Array.isArray(v))return v.filter(Boolean);if(typeof v==='string')return v.split('|').map(x=>x.trim()).filter(Boolean);return [v];}
function g(o,p){return String(p||'search_text').split('.').reduce((c,k)=>c==null?undefined:c[k],o);}
function er(v){return v.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function prep(i){const l=i.location||{};const tags=Array.isArray(i.tags)?i.tags:[];const search_text=[i.source,i.category,i.subtype,i.status,i.county,i.municipality,l.label,l.address,i.title,i.message,...tags].filter(Boolean).join(' ');return {...i,location:l,tags,search_text};}
function run(i){const alert=prep(i),matches=[],rm=new Map();for(const row of rows){if(Number(alert.priority||0)<Number(row.min_priority||1))continue;const sf=a(row.source_filter).map(n);if(sf.length&&!sf.includes(n(alert.source)))continue;const cf=a(row.alert_category_filter).map(n);if(cf.length&&!cf.includes(n(alert.category)))continue;const field=row.match_field||'search_text',h=n(g(alert,field)),cs=[row.search_term,...a(row.aliases)].map(n).filter(Boolean),m=n(row.match_mode);let ok=false;for(const c of cs){if(m==='FIELD'||m==='EXACT')ok=h===c;else if(m==='CONTAINS')ok=h.includes(c);else if(m==='WORD')ok=new RegExp(`(^|\\s)${er(c)}(?=\\s|$)`).test(h);if(ok)break;}if(!ok)continue;matches.push(row.watch_id);for(const r of a(row.recipients)){if(!r||typeof r!=='object')continue;const k=r.subscriber_id||r.ntfy_topic;if(k&&!rm.has(k))rm.set(k,r.subscriber_id||k);}}return {watch_ids:[...new Set(matches)].sort(),recipients:[...new Set(rm.values())].sort()};}
const b={schema_version:'1.0',status:'ACTIVE',event_action:'NEW',county:'HUDSON',priority:4,tags:[],location:{},metadata:{},observed_at:new Date().toISOString(),received_at:new Date().toISOString()};
const tests=[
{name:'town FIELD match',alert:{...b,alert_id:'TEST:TOWN',source:'TEST',category:'OEM',subtype:'NOTICE',municipality:'WEEHAWKEN',title:'Municipal notice',message:'Test municipal alert'},watch_ids:['TEST_W_TOWN'],recipients:['TEST_GIO','TEST_MAYOR','TEST_OEM']},
{name:'source FIELD match',alert:{...b,alert_id:'TEST:SOURCE',source:'PSEG',category:'UTILITY',subtype:'POWER_OUTAGE',municipality:'SECAUCUS',title:'Utility alert',message:'Power outage reported'},watch_ids:['TEST_W_SOURCE'],recipients:['TEST_DPW','TEST_GIO','TEST_OEM']},
{name:'phrase CONTAINS alias match',alert:{...b,alert_id:'TEST:PHRASE',source:'FIRE_SDR',category:'FIRE',subtype:'MAJOR_FIRE',municipality:'NORTH BERGEN',priority:5,title:'Working fire',message:'Second alarm transmitted for the incident'},watch_ids:['TEST_W_PHRASE'],recipients:['TEST_FIRE','TEST_GIO','TEST_OEM','TEST_POLICE']},
{name:'address CONTAINS alias match',alert:{...b,alert_id:'TEST:ADDRESS',source:'FIRE_SDR',category:'FIRE',subtype:'WORKING_FIRE',municipality:'UNION CITY',title:'Working fire',message:'Incident reported at 4100 Park Avenue',location:{label:'4100 Park Avenue',address:'4100 Park Avenue'}},watch_ids:['TEST_W_ADDRESS'],recipients:['TEST_GIO','TEST_MAYOR','TEST_OEM','TEST_POLICE']},
{name:'facility WORD alias match',alert:{...b,alert_id:'TEST:FACILITY',source:'TEST',category:'OEM',subtype:'FACILITY_EVENT',municipality:'UNION CITY',title:'Incident at Weehawken HS',message:'Facility test'},watch_ids:['TEST_W_FACILITY'],recipients:['TEST_FIRE','TEST_GIO','TEST_MAYOR','TEST_OEM','TEST_POLICE']},
{name:'category EXACT match',alert:{...b,alert_id:'TEST:EXACT',source:'NWS',category:'WEATHER',subtype:'ADVISORY',municipality:'NORTH BERGEN',title:'Weather advisory',message:'Test weather alert'},watch_ids:['TEST_W_CATEGORY'],recipients:['TEST_GIO','TEST_OEM']},
{name:'multi-match recipient dedupe',alert:{...b,alert_id:'TEST:MULTI',source:'FIRE_SDR',category:'FIRE',subtype:'2ND_ALARM',municipality:'WEEHAWKEN',priority:5,title:'2nd Alarm - Weehawken',message:'Second alarm transmitted at 4100 Park Avenue',location:{label:'4100 Park Avenue',address:'4100 Park Ave'}},watch_ids:['TEST_W_ADDRESS','TEST_W_PHRASE','TEST_W_TOWN'],recipients:['TEST_FIRE','TEST_GIO','TEST_MAYOR','TEST_OEM','TEST_POLICE']},
{name:'category filter rejects false phrase match',alert:{...b,alert_id:'TEST:FILTER',source:'NJ511',category:'TRAFFIC',subtype:'ROAD_CLOSURE',municipality:'NORTH BERGEN',title:'Road incident',message:'Second alarm wording appears here but category is traffic'},watch_ids:[],recipients:[]}];
const results=tests.map(t=>{const actual=run(t.alert),ew=[...t.watch_ids].sort(),erx=[...t.recipients].sort(),p=JSON.stringify(actual.watch_ids)===JSON.stringify(ew)&&JSON.stringify(actual.recipients)===JSON.stringify(erx);return {name:t.name,passed:p,expected_watch_ids:ew,actual_watch_ids:actual.watch_ids,expected_recipients:erx,actual_recipients:actual.recipients};});
return [{json:{all_passed:results.every(r=>r.passed),tests_run:results.length,passed:results.filter(r=>r.passed).length,failed:results.filter(r=>!r.passed).length,results}}];

